sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float splitDistance;
uniform float angle;

half4 main(float2 coord) {
    float a = radians(angle);
    float2 dir = float2(cos(a), sin(a));
    float2 offset = dir * splitDistance;
    float2 redCoord = coord + offset;
    float2 blueCoord = coord - offset;
    half4 red = image.eval(redCoord);
    half4 blue = image.eval(blueCoord);
    half4 green = image.eval(coord);
    float r = red.a > 0.001 ? red.r / red.a : 0;
    float b = blue.a > 0.001 ? blue.b / blue.a : 0;
    float g = green.g;
    float3 rgb = float3(r, g, b);
    float alpha = min(red.a, min(blue.a, green.a));
    return half4(rgb * alpha, alpha);
}
